<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, toRaw, watch } from 'vue'
import { BookOpenCheck, FileClock, FlaskConical, SearchCheck, ShieldAlert } from '@lucide/vue'
import UiDialog from '../../components/ui/UiDialog.vue'
import { useProjectsStore } from '../../stores/projects'
import { adviceError, alertAdviceApi, systemKnowledgeApi, type SystemKnowledgeVersion, type KnowledgeDraft, type KnowledgeEntry, type KnowledgePayload, type KnowledgeRevision, type KnowledgeStatus } from './api'
import './knowledge.css'

const projects = useProjectsStore()
const props = defineProps<{ system?: boolean }>()
const api = computed(() => props.system ? systemKnowledgeApi : alertAdviceApi)
const versions = ref<SystemKnowledgeVersion[]>([]), catalogRevision = ref(1), publishedVersion = ref(0)
const publishOpen = ref(false), releaseOpen = ref(false)
const releaseEntries = ref<KnowledgeEntry[]>([]), releaseVersion = ref(0), publishNotes = ref(''), publishRevision = ref(0)
const entries = ref<KnowledgeEntry[]>([]), loading = ref(true), busy = ref(false), error = ref(''), mutationError = ref(''), notice = ref('')
const filter = reactive({ status: '' as '' | KnowledgeStatus, alertTypeId: '', recognitionCategoryId: '' })
const editOpen = ref(false), detailOpen = ref(false), historyOpen = ref(false), previewOpen = ref(false)
const selected = ref<KnowledgeEntry>(), revisions = ref<KnowledgeRevision[]>([]), preview = ref<{ matched: boolean; key: string; entry?: KnowledgeEntry }>()
let controller = new AbortController()
const canManage = computed(() => Boolean(props.system))
const emptyDraft = (): KnowledgeDraft => ({ entryId: '', alertTypeId: '', recognitionCategoryId: '', status: 'ACTIVE', title: '', riskDescription: '', adviceTemplate: { title: '', steps: [{ stepId: 'step-1', order: 1, title: '', instruction: '' }], cautions: ['请结合现场条件和适用制度核实；本建议不构成违规认定。'] }, references: [{ referenceId: 'reference-1', documentTitle: '', documentNumber: null, documentVersion: 'demo-v1', chapter: null, clauseId: null, excerpt: '', sourceName: 'AI YOLO 演示模拟知识库', sourceType: 'MOCK_KNOWLEDGE_BASE', effectiveDate: null }], applicability: '', sourceType: 'MOCK_KNOWLEDGE_BASE' })
const draft = reactive<KnowledgeDraft>(emptyDraft())

function payload(): KnowledgePayload { return { title: draft.title.trim(), riskDescription: draft.riskDescription.trim(), adviceTemplate: { title: draft.adviceTemplate.title.trim(), steps: draft.adviceTemplate.steps.map((step, index) => ({ ...step, stepId: step.stepId.trim(), order: index + 1, title: step.title.trim(), instruction: step.instruction.trim() })), cautions: draft.adviceTemplate.cautions.map(v => v.trim()).filter(Boolean) }, references: draft.references.map(reference => ({ ...reference, referenceId: reference.referenceId.trim(), documentTitle: reference.documentTitle.trim(), documentVersion: reference.documentVersion.trim(), excerpt: reference.excerpt.trim(), sourceName: reference.sourceName.trim(), documentNumber: reference.documentNumber?.trim() || null, chapter: reference.chapter?.trim() || null, clauseId: reference.clauseId?.trim() || null, effectiveDate: reference.effectiveDate?.trim() || null })), applicability: draft.applicability.trim(), sourceType: 'MOCK_KNOWLEDGE_BASE' } }
async function load() {
  controller.abort(); const current = controller = new AbortController(); loading.value = true; error.value = ''
  try {
    let items: KnowledgeEntry[]
    if (props.system) {
      const [catalog, published] = await Promise.all([systemKnowledgeApi.catalog(current.signal), systemKnowledgeApi.versions(current.signal)])
      if (current.signal.aborted) return
      items = catalog.entries; catalogRevision.value = catalog.revision; versions.value = published.versions; publishedVersion.value = published.versions.at(-1)?.version ?? 0
    } else {
      const catalog = await alertAdviceApi.catalog(current.signal)
      if (current.signal.aborted) return
      publishedVersion.value = catalog.systemVersion; versions.value = []; items = catalog.entries
    }
    entries.value = items.filter(item => (!filter.status || item.status === filter.status) && (!filter.alertTypeId.trim() || item.matchKey.alertTypeId === filter.alertTypeId.trim().toUpperCase()) && (!filter.recognitionCategoryId.trim() || item.matchKey.recognitionCategoryId === filter.recognitionCategoryId.trim().toUpperCase()))
  } catch (e) { if (!current.signal.aborted) { error.value = adviceError(e); entries.value = [] } } finally { if (!current.signal.aborted) loading.value = false }
}
function begin(entry?: KnowledgeEntry) { if (!canManage.value) return; selected.value = entry; mutationError.value = ''; notice.value = ''; Object.assign(draft, entry ? { ...entry, alertTypeId: entry.matchKey.alertTypeId, recognitionCategoryId: entry.matchKey.recognitionCategoryId, adviceTemplate: structuredClone(toRaw(entry.adviceTemplate)), references: structuredClone(toRaw(entry.references)) } : emptyDraft()); editOpen.value = true }
function addStep() { draft.adviceTemplate.steps.push({ stepId: 'step-' + (draft.adviceTemplate.steps.length + 1), order: draft.adviceTemplate.steps.length + 1, title: '', instruction: '' }) }
function addReference() { draft.references.push({ referenceId: 'reference-' + (draft.references.length + 1), documentTitle: '', documentNumber: null, documentVersion: 'demo-v1', chapter: null, clauseId: '', excerpt: '', sourceName: 'AI YOLO 演示模拟知识库', sourceType: 'MOCK_KNOWLEDGE_BASE', effectiveDate: null }) }
async function save() { if (!canManage.value) return; busy.value = true; mutationError.value = ''; try { if (selected.value) await systemKnowledgeApi.update(selected.value, payload()); else await systemKnowledgeApi.create({ ...payload(), entryId: draft.entryId.trim(), alertTypeId: draft.alertTypeId.trim(), recognitionCategoryId: draft.recognitionCategoryId.trim(), status: draft.status }); editOpen.value = false; notice.value = '系统草稿已保存；发布后所有项目统一使用，无需项目升级。'; await load() } catch (e) { mutationError.value = adviceError(e) } finally { busy.value = false } }
async function changeStatus(entry: KnowledgeEntry) { if (!canManage.value) return; busy.value = true; mutationError.value = ''; try { await systemKnowledgeApi.status(entry, entry.status === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE'); notice.value = '系统草稿状态已修改；发布后对所有项目统一生效。'; await load() } catch (e) { mutationError.value = adviceError(e) } finally { busy.value = false } }
function inspect(entry: KnowledgeEntry) { selected.value = entry; detailOpen.value = true }
async function history(entry: KnowledgeEntry) { selected.value = entry; historyOpen.value = true; revisions.value = []; try { revisions.value = await api.value.revisions(entry.entryId) } catch (e) { mutationError.value = adviceError(e) } }
async function runPreview() { mutationError.value = ''; try { const result = await api.value.preview(filter.alertTypeId.trim(), filter.recognitionCategoryId.trim()); preview.value = { matched: result.matched, key: result.matchKey.alertTypeId + ' + ' + result.matchKey.recognitionCategoryId, entry: result.entry ?? undefined }; previewOpen.value = true } catch (e) { mutationError.value = adviceError(e) } }
function beginPublish() { if (!canManage.value) return; publishRevision.value = catalogRevision.value; publishNotes.value = ''; mutationError.value = ''; publishOpen.value = true }
async function publish() { if (!canManage.value) return; busy.value = true; mutationError.value = ''; try { await systemKnowledgeApi.publish(publishRevision.value, publishNotes.value.trim()); publishOpen.value = false; notice.value = '已发布系统版本；所有项目后续查询和生成统一使用最新资料，历史建议保持不变。'; await load() } catch (e) { mutationError.value = adviceError(e) } finally { busy.value = false } }
async function viewRelease(version: number) { busy.value = true; mutationError.value = ''; try { releaseEntries.value = (await systemKnowledgeApi.release(version)).entries; releaseVersion.value = version; releaseOpen.value = true } catch (e) { mutationError.value = adviceError(e) } finally { busy.value = false } }
watch(() => [props.system, projects.current?.projectId], () => { editOpen.value = detailOpen.value = historyOpen.value = previewOpen.value = publishOpen.value = releaseOpen.value = false; notice.value = ''; mutationError.value = ''; void load() }, { immediate: true }); onBeforeUnmount(() => controller.abort())
</script>

<template><section class="knowledge-workspace">
  <section class="knowledge-base-panel" aria-label="系统统一知识资料">
    <template v-if="system"><div><small>系统基础资料</small><h3>草稿维护 · 显式发布</h3><p>只维护一份系统资料。草稿发布后所有项目统一使用，历史建议保留原快照。</p></div><details><summary>已发布版本（{{ versions.length }}）</summary><article v-for="version in [...versions].reverse()" :key="version.version" class="base-version"><strong>V{{ version.version }} · {{ version.entryCount }} 条</strong><p>{{ version.notes }}</p><small>{{ new Date(version.publishedAt).toLocaleString('zh-CN') }}</small><UiButton class="secondary-button" :disabled="busy" @click="viewRelease(version.version)">查看发布快照</UiButton></article></details></template>
    <template v-else><div><small>系统统一知识资料 · 只读使用</small><h3>{{ publishedVersion ? '当前发布 V' + publishedVersion : '读取系统资料' }}</h3><p>所有项目使用同一份最新发布资料；此页面仅供查询和使用，维护请前往平台系统知识资料。</p></div></template>
  </section>
  <div class="knowledge-actions page-actions"><UiButton class="secondary-button" :disabled="loading || busy" @click="load">刷新台账</UiButton><UiButton v-if="canManage" class="primary-button" :disabled="loading || busy" @click="begin()">新增系统草稿资料</UiButton><UiButton v-if="system" class="primary-button" :disabled="loading || busy || !!error" @click="beginPublish">发布系统版本</UiButton></div>
  <div class="simulation-strip"><FlaskConical :size="20" /><div><strong>模拟数据模式</strong><span>当前不会上传制度文档，也不会调用在线大模型；系统资料仅由平台管理员维护和发布，项目成员只读使用。</span></div></div>
  <form class="knowledge-filter" @submit.prevent="load"><label>状态<select v-model="filter.status"><option value="">全部状态</option><option value="ACTIVE">已启用</option><option value="INACTIVE">已停用</option></select></label><label>告警类型 ID<UiInput v-model="filter.alertTypeId" placeholder="例如 PPE_NO_HELMET" /></label><label>识别分类 ID<UiInput v-model="filter.recognitionCategoryId" placeholder="例如 HEAD" /></label><UiButton class="secondary-button">筛选</UiButton><UiButton type="button" class="preview-button" :disabled="!filter.alertTypeId.trim() || !filter.recognitionCategoryId.trim()" @click="runPreview"><SearchCheck :size="17" />匹配预览</UiButton></form>
  <p v-if="notice" class="knowledge-success" role="status">{{ notice }}</p><p v-if="mutationError" class="knowledge-error" role="alert">{{ mutationError }}</p>
  <div v-if="loading" class="knowledge-state">正在读取知识资料台账…</div><div v-else-if="error" class="knowledge-state is-error" role="alert"><strong>资料读取失败</strong><span>{{ error }}</span><UiButton class="secondary-button" @click="load">重试</UiButton></div><div v-else-if="!entries.length" class="knowledge-state"><BookOpenCheck :size="28" /><strong>暂无匹配资料</strong><span>请调整筛选条件；资料由平台管理员统一维护。</span></div>
  <div v-else class="knowledge-ledger"><article v-for="entry in entries" :key="entry.entryId" class="knowledge-card"><header><div><span class="knowledge-status" :class="entry.status.toLowerCase()">{{ entry.status === 'ACTIVE' ? '参与匹配' : '已停用' }}</span><span class="mock-chip">{{ system ? '系统草稿' : '系统统一 V' + entry.systemVersion }}</span></div><small>REV {{ String(entry.revision).padStart(2, '0') }}</small></header><h3>{{ entry.title }}</h3><p class="match-key"><span>{{ entry.matchKey.alertTypeId }}</span><b>+</b><span>{{ entry.matchKey.recognitionCategoryId }}</span></p><p class="risk-copy">{{ entry.riskDescription }}</p><dl><div><dt>处置步骤</dt><dd>{{ entry.adviceTemplate.steps.length }} 项</dd></div><div><dt>制度引用</dt><dd>{{ entry.references.length }} 条</dd></div><div><dt>最近维护</dt><dd>{{ new Date(entry.updatedAt).toLocaleString('zh-CN') }}</dd></div></dl><footer><UiButton class="secondary-button" @click="inspect(entry)">查看详情</UiButton><UiButton class="secondary-button" @click="history(entry)"><FileClock :size="16" />版本</UiButton><UiButton v-if="canManage" class="secondary-button" :disabled="busy" @click="begin(entry)">编辑</UiButton><UiButton v-if="canManage" class="status-button" :disabled="busy" @click="changeStatus(entry)">{{ entry.status === 'ACTIVE' ? '停用' : '启用' }}</UiButton></footer></article></div>

  <UiDialog v-if="system" v-model:open="editOpen" :title="selected ? '编辑系统知识资料' : '新增系统模拟资料'" :busy="busy"><form class="knowledge-form" @submit.prevent="save"><fieldset :disabled="busy"><div class="form-grid"><label>资料 ID<UiInput v-model="draft.entryId" required :readonly="!!selected" /></label><label>初始状态<select v-model="draft.status" :disabled="!!selected"><option value="ACTIVE">已启用</option><option value="INACTIVE">已停用</option></select></label><label>告警类型 ID<UiInput v-model="draft.alertTypeId" required :readonly="!!selected" /></label><label>识别分类 ID<UiInput v-model="draft.recognitionCategoryId" required :readonly="!!selected" /></label></div><label>资料标题<UiInput v-model="draft.title" required maxlength="300" /></label><label>风险说明<textarea v-model="draft.riskDescription" required maxlength="2000"></textarea></label><label>建议标题<UiInput v-model="draft.adviceTemplate.title" required /></label><section class="form-array"><header><h4>处置步骤</h4><UiButton type="button" class="secondary-button" @click="addStep">增加步骤</UiButton></header><article v-for="(step, index) in draft.adviceTemplate.steps" :key="index"><span class="array-number">{{ index + 1 }}</span><label>步骤 ID<UiInput v-model="step.stepId" required /></label><label>标题<UiInput v-model="step.title" required /></label><label class="wide">操作说明<textarea v-model="step.instruction" required></textarea></label><UiButton v-if="draft.adviceTemplate.steps.length > 1" type="button" class="remove-button" @click="draft.adviceTemplate.steps.splice(index, 1)">移除</UiButton></article></section><section class="form-array references"><header><div><h4>可能相关的制度依据</h4><p>“制度原文”与 AI 建议严格分字段保存。</p></div><UiButton type="button" class="secondary-button" @click="addReference">增加制度</UiButton></header><article v-for="(reference, index) in draft.references" :key="index"><span class="array-number">R{{ index + 1 }}</span><label>引用 ID<UiInput v-model="reference.referenceId" required /></label><label>制度标题<UiInput v-model="reference.documentTitle" required /></label><label>版本<UiInput v-model="reference.documentVersion" required /></label><label>条款号<UiInput v-model="reference.clauseId" /></label><label class="wide">制度原文<textarea v-model="reference.excerpt" required></textarea></label><label class="wide">资料来源<UiInput v-model="reference.sourceName" required /></label><UiButton v-if="draft.references.length > 1" type="button" class="remove-button" @click="draft.references.splice(index, 1)">移除</UiButton></article></section><label>适用条件<textarea v-model="draft.applicability" required></textarea></label></fieldset><p v-if="mutationError" class="knowledge-error" role="alert">{{ mutationError }}</p><footer class="dialog-actions"><UiButton type="button" class="secondary-button" :disabled="busy" @click="editOpen = false">取消</UiButton><UiButton class="primary-button" :loading="busy">保存资料</UiButton></footer></form></UiDialog>
  <UiDialog v-model:open="detailOpen" title="知识资料详情"><article v-if="selected" class="knowledge-detail"><div class="detail-title"><ShieldAlert :size="24" /><div><span>{{ selected.matchKey.alertTypeId }} + {{ selected.matchKey.recognitionCategoryId }}</span><h3>{{ selected.title }}</h3></div></div><h4>处置建议</h4><ol><li v-for="step in selected.adviceTemplate.steps" :key="step.stepId"><strong>{{ step.title }}</strong><p>{{ step.instruction }}</p></li></ol><h4>可能相关的制度依据</h4><blockquote v-for="reference in selected.references" :key="reference.referenceId"><strong>{{ reference.documentTitle }} · {{ reference.clauseId || reference.documentVersion }}</strong><p>{{ reference.excerpt }}</p><cite>{{ reference.sourceName }} / {{ reference.sourceType }}</cite></blockquote><p class="simulation-disclaimer">模拟资料仅供演示和人工处置参考，不构成违法违规认定。</p></article></UiDialog>
  <UiDialog v-model:open="historyOpen" :title="system ? '资料版本历史' : '当前系统发布修订'"><div class="revision-list"><article v-for="revision in revisions" :key="revision.revision"><span>REV {{ revision.revision }}</span><strong>{{ revision.action }}</strong><p>{{ revision.actor }} · {{ new Date(revision.createdAt).toLocaleString('zh-CN') }}</p></article><p v-if="!revisions.length">正在读取或暂无版本记录…</p></div></UiDialog>
  <UiDialog v-model:open="previewOpen" title="精确匹配预览"><div v-if="preview" class="preview-result" :class="{ matched: preview.matched }"><SearchCheck :size="28" /><strong>{{ preview.matched ? '找到精确匹配资料' : '未找到精确匹配资料' }}</strong><code>{{ preview.key }}</code><p>{{ preview.matched ? preview.entry?.title : '系统不会按显示名称、模型名称或相似分类进行兜底匹配。' }}</p></div></UiDialog>
  <UiDialog v-if="system" v-model:open="publishOpen" title="发布系统基础版本" :busy="busy"><form class="knowledge-form" @submit.prevent="publish"><p>将所见草稿发布为新版本。所有项目后续查询和生成统一使用新版本，既有建议历史不变。</p><label>发布说明<textarea v-model="publishNotes" required maxlength="2000" :disabled="busy"></textarea></label><p v-if="mutationError" role="alert">{{ mutationError }}</p><footer class="dialog-actions"><UiButton type="button" class="secondary-button" :disabled="busy" @click="publishOpen = false">取消</UiButton><UiButton class="primary-button" :loading="busy" :disabled="!publishNotes.trim()">确认发布</UiButton></footer></form></UiDialog>
  <UiDialog v-model:open="releaseOpen" :title="'系统 V' + releaseVersion + ' · 发布快照'"><div class="knowledge-detail"><article v-for="entry in releaseEntries" :key="entry.entryId"><h3>{{ entry.title }}</h3><p>{{ entry.matchKey.alertTypeId }} + {{ entry.matchKey.recognitionCategoryId }} · {{ entry.status }}</p><ol><li v-for="step in entry.adviceTemplate.steps" :key="step.stepId"><strong>{{ step.title }}</strong><p>{{ step.instruction }}</p></li></ol><blockquote v-for="reference in entry.references" :key="reference.referenceId"><strong>{{ reference.documentTitle }} · {{ reference.clauseId || reference.documentVersion }}</strong><p>{{ reference.excerpt }}</p></blockquote></article></div></UiDialog>
</section></template>
